SELECT rule, passed FROM (
 SELECT 'Members cannot assign their own roles' AS rule, NOT has_table_privilege('authenticated','public.user_roles','INSERT') AS passed
 UNION ALL SELECT 'Members cannot make themselves super admin', NOT has_table_privilege('authenticated','public.super_admins','INSERT')
 UNION ALL SELECT 'Francis is the only super admin', (SELECT count(*) = 1 AND bool_and(u.email = 'franciserazua59@gmail.com') FROM public.super_admins s JOIN auth.users u ON u.id = s.user_id)
 UNION ALL SELECT 'Only admins can upload site media', EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND policyname='site_media_admin_insert' AND with_check LIKE '%has_role%')
 UNION ALL SELECT 'Visitors cannot read member profiles', NOT has_table_privilege('anon','public.profiles','SELECT')
 UNION ALL SELECT 'Members can change their display name', has_column_privilege('authenticated','public.profiles','display_name','UPDATE')
 UNION ALL SELECT 'Members cannot change wallet balances', NOT has_table_privilege('authenticated','public.wallet_accounts','UPDATE')
 UNION ALL SELECT 'Members cannot invent wallet credits', NOT has_table_privilege('authenticated','public.wallet_transactions','INSERT')
 UNION ALL SELECT 'Wallet totals stay private to signed-in members', has_function_privilege('authenticated','public.get_wallet_ledger_totals(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.get_wallet_ledger_totals(uuid)','EXECUTE')
 UNION ALL SELECT 'Members cannot mark press releases paid', NOT has_column_privilege('authenticated','public.press_releases','paid_at','UPDATE')
 UNION ALL SELECT 'Members can draft articles before payment', has_column_privilege('authenticated','public.press_releases','content_draft','INSERT')
 UNION ALL SELECT 'Members cannot pay themselves survey rewards', NOT has_function_privilege('authenticated','public.settle_survey_answer(uuid, uuid, jsonb, integer, text, text)','EXECUTE') AND NOT has_function_privilege('anon','public.settle_survey_answer(uuid, uuid, jsonb, integer, text, text)','EXECUTE')
 UNION ALL SELECT 'Members cannot release survey points themselves', NOT has_function_privilege('authenticated','public.refund_survey_escrow(uuid)','EXECUTE')
 UNION ALL SELECT 'Members cannot confirm press payments themselves', NOT has_function_privilege('authenticated','public.settle_press_release_payment(text, bigint, text, text)','EXECUTE') AND NOT has_function_privilege('anon','public.settle_press_release_payment(text, bigint, text, text)','EXECUTE')
 UNION ALL SELECT 'Only the press desk can move press bookings', NOT has_function_privilege('authenticated','public.update_press_release_stage(uuid, text, text, text)','EXECUTE') AND NOT has_function_privilege('anon','public.update_press_release_stage(uuid, text, text, text)','EXECUTE')
 UNION ALL SELECT 'Members cannot change press prices', NOT has_column_privilege('authenticated','public.press_releases','quote_minor','UPDATE') AND NOT has_column_privilege('authenticated','public.press_releases','price_usd_cents','UPDATE')
 UNION ALL SELECT 'Members cannot set shop order prices', NOT has_table_privilege('authenticated','public.shop_orders','INSERT')
 UNION ALL SELECT 'Every foundation table has row protection', count(*)=10 AND bool_and(c.relrowsecurity) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('profiles','user_roles','surveys','survey_answers','wallet_accounts','wallet_transactions','withdrawals','press_releases','kit_quotes','shop_orders')
) checks ORDER BY rule;